"use client";

import { useId, useRef, useState } from "react";
import { motion } from "framer-motion";
import { ThumbsDown, ThumbsUp } from "lucide-react";
import { LiveRegion } from "@/components/bjork-ui/_core/a11y";
import { easeCss, springs } from "@/components/bjork-ui/_core/motion";
import {
  FOCUS_RING,
  PRESS,
  useAiTone,
  useControllable,
  useReduceMotion,
  type BjorkTone,
} from "@/components/bjork-ui/ai/_shared";
import { cn } from "@/lib/utils";

export type FeedbackRating = "up" | "down";

export interface FeedbackPayload {
  rating: FeedbackRating;
  reasons: string[];
  comment: string;
}

export interface ResponseFeedbackProps {
  /** Controlled rating. `null` is no rating. */
  value?: FeedbackRating | null;
  defaultValue?: FeedbackRating | null;
  onValueChange?: (value: FeedbackRating | null) => void;
  /** Reason chips per polarity. Defaults to `SAMPLE_FEEDBACK_REASONS`. */
  reasons?: Partial<Record<FeedbackRating, string[]>>;
  onSubmit?: (feedback: FeedbackPayload) => void;
  /** Called when a sent rating is undone. */
  onUndo?: () => void;
  /** Show the optional comment field. Default true. */
  allowComment?: boolean;
  /** Initial panel state, for a rating that should open with its panel. Default false. */
  defaultOpen?: boolean;
  /** Initially selected reasons. */
  defaultReasons?: string[];
  tone?: BjorkTone;
  className?: string;
}

export const SAMPLE_FEEDBACK_REASONS: Record<FeedbackRating, string[]> = {
  up: ["Accurate", "Clear", "Well sourced", "Right length"],
  down: ["Inaccurate", "Didn't follow instructions", "Too long", "Outdated sources", "Unsafe or harmful"],
};

const PROMPT: Record<FeedbackRating, string> = {
  up: "What worked?",
  down: "What went wrong?",
};

/**
 * Thumbs up and down for an AI answer. A rating opens a short panel of reasons and an optional comment, then folds
 * into a quiet receipt with Undo.
 */
export function ResponseFeedback({
  value,
  defaultValue = null,
  onValueChange,
  reasons = SAMPLE_FEEDBACK_REASONS,
  onSubmit,
  onUndo,
  allowComment = true,
  defaultOpen = false,
  defaultReasons = [],
  tone: toneProp,
  className,
}: ResponseFeedbackProps) {
  const { style } = useAiTone(toneProp);
  const reduce = useReduceMotion();
  const [rating, setRating] = useControllable<FeedbackRating | null>(value, defaultValue, onValueChange);
  const [open, setOpen] = useState(defaultOpen && defaultValue !== null);
  const [sent, setSent] = useState(false);
  const [picked, setPicked] = useState<string[]>(defaultReasons);
  const [comment, setComment] = useState("");
  const [message, setMessage] = useState("");
  const [bump, setBump] = useState(0); // replays the press flourish on the chosen thumb
  const panelId = useId();
  const commentId = useId();
  const upRef = useRef<HTMLButtonElement>(null);
  const downRef = useRef<HTMLButtonElement>(null);

  const reset = () => {
    setPicked([]);
    setComment("");
  };

  const choose = (next: FeedbackRating) => {
    if (sent) return;
    if (rating === next) {
      setRating(null);
      setOpen(false);
      reset();
      return;
    }
    reset();
    setRating(next);
    setOpen(true);
    setBump((b) => b + 1);
  };

  const focusThumb = (which: FeedbackRating | null) =>
    requestAnimationFrame(() => (which === "down" ? downRef : upRef).current?.focus());

  const cancel = () => {
    const was = rating;
    setOpen(false);
    setRating(null);
    reset();
    focusThumb(was);
  };

  const submit = () => {
    if (!rating) return;
    onSubmit?.({ rating, reasons: picked, comment: comment.trim() });
    setOpen(false);
    setSent(true);
    setMessage("Thanks, feedback sent");
    focusThumb(rating);
  };

  const undo = () => {
    const was = rating;
    setSent(false);
    setRating(null);
    reset();
    onUndo?.();
    setMessage("Feedback removed");
    focusThumb(was);
  };

  const toggle = (reason: string) =>
    setPicked((list) => (list.includes(reason) ? list.filter((r) => r !== reason) : [...list, reason]));

  const list = rating ? (reasons[rating] ?? []) : [];
  const panelOpen = open && rating !== null && !sent;

  return (
    <div
      role="group"
      aria-label="Rate this response"
      className={cn("@container w-full max-w-[460px] font-bjork-alpha text-[color:var(--bjork-text)]", className)}
      style={style}
    >
      <div className="-ml-2 flex min-h-8 items-center gap-0.5">
        {(["up", "down"] as const).map((kind) => {
          const selected = rating === kind;
          const Icon = kind === "up" ? ThumbsUp : ThumbsDown;
          return (
            <button
              key={kind}
              ref={kind === "up" ? upRef : downRef}
              type="button"
              aria-pressed={selected}
              aria-label={kind === "up" ? "Good response" : "Bad response"}
              aria-expanded={selected ? panelOpen : undefined}
              aria-controls={selected ? panelId : undefined}
              onClick={() => choose(kind)}
              className={cn(
                "grid size-8 cursor-pointer place-items-center rounded-[8px] transition-colors",
                selected
                  ? "text-[color:var(--bjork-accent-ink)]"
                  : "text-[color:var(--bjork-text-faint)] hover:bg-[var(--bjork-surface-active)] hover:text-[color:var(--bjork-text)]",
                sent && !selected && "pointer-events-none opacity-40",
                FOCUS_RING,
                PRESS,
              )}
            >
              <motion.span
                key={selected ? `on-${bump}` : "off"}
                className="grid place-items-center"
                initial={reduce || !selected ? false : { rotate: kind === "up" ? -14 : 14, y: kind === "up" ? -1.5 : 1.5 }}
                animate={{ rotate: 0, y: 0 }}
                transition={springs.press}
              >
                <Icon
                  size={15}
                  strokeWidth={1.75}
                  fill={selected ? "currentColor" : "none"}
                  fillOpacity={selected ? 0.18 : 0}
                />
              </motion.span>
            </button>
          );
        })}

        <span
          className={cn(
            "ml-2 flex min-w-0 items-center gap-2 text-[13px] leading-5 text-[color:var(--bjork-text-muted)] transition-opacity duration-200",
            sent ? "opacity-100" : "pointer-events-none opacity-0",
          )}
          aria-hidden={!sent || undefined}
          inert={!sent}
        >
          <span className="truncate">Thanks — feedback sent</span>
          <button
            type="button"
            onClick={undo}
            className={cn(
              "-my-1 h-7 shrink-0 cursor-pointer rounded-[6px] px-1.5 font-medium text-[color:var(--bjork-text)] underline decoration-[color:var(--bjork-border-strong)] underline-offset-[3px] transition-colors hover:decoration-[color:var(--bjork-text)]",
              FOCUS_RING,
            )}
          >
            Undo
          </button>
        </span>
      </div>

      <div
        id={panelId}
        aria-hidden={!panelOpen || undefined}
        inert={!panelOpen}
        className="grid"
        style={{
          gridTemplateRows: panelOpen ? "1fr" : "0fr",
          opacity: panelOpen ? 1 : 0,
          transition: reduce ? "none" : `grid-template-rows 280ms ${easeCss.drawer}, opacity 220ms ${easeCss.drawer}`,
        }}
      >
        <div className="min-h-0 overflow-hidden">
          <form
            aria-label="Feedback details"
            className="mt-2 rounded-[12px] border border-[color:var(--bjork-border)] p-3"
            onSubmit={(e) => {
              e.preventDefault();
              submit();
            }}
            onKeyDown={(e) => {
              if (e.key === "Escape") {
                e.preventDefault();
                cancel();
              }
            }}
          >
            <p className="font-mono text-[10px] uppercase leading-4 tracking-[0.08em] text-[color:var(--bjork-text-faint)]">
              {rating ? PROMPT[rating] : ""}
            </p>
            <div className="mt-2.5 flex flex-wrap gap-1.5">
              {list.map((reason) => {
                const on = picked.includes(reason);
                return (
                  <button
                    key={reason}
                    type="button"
                    aria-pressed={on}
                    onClick={() => toggle(reason)}
                    className={cn(
                      "h-7 cursor-pointer rounded-full border px-2.5 text-[12px] font-medium leading-none transition-colors duration-150",
                      on
                        ? "border-[color:var(--bjork-accent-muted)] bg-[var(--bjork-accent-soft)] text-[color:var(--bjork-accent-ink)]"
                        : "border-[color:var(--bjork-border)] text-[color:var(--bjork-text-muted)] hover:border-[color:var(--bjork-border-strong)] hover:text-[color:var(--bjork-text)]",
                      FOCUS_RING,
                      PRESS,
                    )}
                  >
                    {reason}
                  </button>
                );
              })}
            </div>
            {allowComment && (
              <>
                <label htmlFor={commentId} className="sr-only">
                  Comment (optional)
                </label>
                <textarea
                  id={commentId}
                  value={comment}
                  onChange={(e) => setComment(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                      e.preventDefault();
                      submit();
                    }
                  }}
                  rows={2}
                  maxLength={600}
                  placeholder="Add a comment (optional)"
                  className={cn(
                    "mt-3 block min-h-[56px] w-full resize-none rounded-[9px] border border-[color:var(--bjork-border)] bg-[var(--bjork-field-inset)] px-2.5 py-2 text-[13px] leading-5 text-[color:var(--bjork-text)] transition-colors [field-sizing:content] placeholder:text-[color:var(--bjork-text-faint)] hover:border-[color:var(--bjork-border-strong)]",
                    FOCUS_RING,
                  )}
                />
              </>
            )}
            <div className="mt-3 flex items-center justify-end gap-1.5">
              <button
                type="button"
                onClick={cancel}
                className={cn(
                  "h-8 cursor-pointer rounded-[9px] px-3 text-[13px] font-medium text-[color:var(--bjork-text-muted)] transition-colors hover:bg-[var(--bjork-surface-active)] hover:text-[color:var(--bjork-text)]",
                  FOCUS_RING,
                  PRESS,
                )}
              >
                Cancel
              </button>
              <button
                type="submit"
                className={cn(
                  "h-8 cursor-pointer rounded-[9px] bg-[color:var(--bjork-accent)] px-3 text-[13px] font-medium text-[color:var(--bjork-accent-foreground)] transition-opacity hover:opacity-90",
                  FOCUS_RING,
                  PRESS,
                )}
              >
                Submit
              </button>
            </div>
          </form>
        </div>
      </div>

      <LiveRegion message={message} />
    </div>
  );
}

import type { ReactNode } from "react";

// Text for assistive tech only.
export function VisuallyHidden({ children }: { children: ReactNode }) {
  return <span className="sr-only">{children}</span>;
}

// Announces `message` when it changes. Same text re-rendered does not re-announce.
export function LiveRegion({
  message,
  politeness = "polite",
}: {
  message: string;
  politeness?: "polite" | "assertive";
}) {
  return (
    <span role="status" aria-live={politeness} aria-atomic="true" className="sr-only">
      {message}
    </span>
  );
}

// Shared springs, easings and durations. Components import these instead of inventing values.

export const springs = {
  press: { type: "spring", stiffness: 500, damping: 30, mass: 0.6 },
  snappy: { type: "spring", stiffness: 400, damping: 25, mass: 1 },
  standard: { type: "spring", stiffness: 300, damping: 30, mass: 0.8 },
  soft: { type: "spring", stiffness: 200, damping: 25, mass: 1.2 },
  settle: { type: "spring", stiffness: 380, damping: 30, mass: 0.8 },
  blurIn: { type: "spring", stiffness: 400, damping: 28, mass: 0.6 },
} as const;

export const ease = {
  out: [0.23, 1, 0.32, 1],
  inOut: [0.77, 0, 0.175, 1],
  drawer: [0.32, 0.72, 0, 1],
} as const;

export const easeCss = {
  out: "cubic-bezier(0.23,1,0.32,1)",
  inOut: "cubic-bezier(0.77,0,0.175,1)",
  drawer: "cubic-bezier(0.32,0.72,0,1)",
} as const;

export const durations = { press: 140, tooltip: 160, menu: 200, panel: 280 } as const; // ms

// Cubic bezier easing for canvas and rAF code. Returns progress y for input x in [0, 1].
export function cubicBezier(x1: number, y1: number, x2: number, y2: number): (t: number) => number {
  const cx = 3 * x1;
  const bx = 3 * (x2 - x1) - cx;
  const ax = 1 - cx - bx;
  const cy = 3 * y1;
  const by = 3 * (y2 - y1) - cy;
  const ay = 1 - cy - by;
  const sampleX = (s: number) => ((ax * s + bx) * s + cx) * s;
  const sampleY = (s: number) => ((ay * s + by) * s + cy) * s;
  const sampleDX = (s: number) => (3 * ax * s + 2 * bx) * s + cx;

  const solveX = (x: number) => {
    let s = x;
    for (let i = 0; i < 8; i++) {
      const err = sampleX(s) - x;
      if (Math.abs(err) < 1e-6) return s;
      const d = sampleDX(s);
      if (Math.abs(d) < 1e-6) break;
      s -= err / d;
    }
    let lo = 0;
    let hi = 1;
    s = x;
    while (lo < hi) {
      const v = sampleX(s);
      if (Math.abs(v - x) < 1e-6) return s;
      if (x > v) lo = s;
      else hi = s;
      s = (lo + hi) / 2;
      if (hi - lo < 1e-7) break;
    }
    return s;
  };

  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    return sampleY(solveX(t));
  };
}

"use client";

// Shared plumbing for the bjork-ui AI components: tone tokens, reduced motion, controllable state and
// number formatting. Every AI component imports from here so they read as one family.

import {
  useCallback,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
  type CSSProperties,
} from "react";
import { useReducedMotion } from "framer-motion";
import { BJORK_PALETTE, type BjorkTone } from "@/components/bjork-ui/_core/palette";
import { useBjorkTone } from "@/components/bjork-ui/_core/tone";
import { surfaceVars } from "@/components/bjork-ui/_core/surface";

export type { BjorkTone };
export type BjorkPalette = (typeof BJORK_PALETTE)[BjorkTone];

const noopSubscribe = () => () => {};

/** False on the server and the first client render, true after hydration. */
export function useHydrated(): boolean {
  return useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false,
  );
}

/** Hydration-safe reduced motion: both sides report "not reduced" until mount, then the real value applies. */
export function useReduceMotion(): boolean {
  const hydrated = useHydrated();
  const reduced = useReducedMotion();
  return hydrated && reduced === true;
}

/**
 * Resolves the tone and returns the CSS custom properties for it. Spread `style` on the component root so an
 * explicit `tone` prop wins over the page theme, and status colours (success, warning, error) are always defined.
 */
export function useAiTone(toneProp?: BjorkTone) {
  const tone = useBjorkTone(toneProp);
  const pal = BJORK_PALETTE[tone];
  const style = {
    ...surfaceVars(tone),
    "--bjork-text": pal.text,
    "--bjork-text-medium": pal.textMedium,
    "--bjork-text-muted": pal.textMuted,
    "--bjork-text-soft": pal.textSoft,
    "--bjork-text-faint": pal.textFaint,
    "--bjork-hair": pal.hair,
    "--bjork-border": pal.border,
    "--bjork-border-strong": pal.borderStrong,
    "--bjork-surface": pal.surface,
    "--bjork-raised": pal.raised,
    "--bjork-surface-active": pal.active,
    "--bjork-accent": pal.accent,
    "--bjork-accent-ink": pal.accentInk,
    "--bjork-accent-fill": pal.accentFill,
    "--bjork-accent-soft": pal.accentSoft,
    "--bjork-accent-muted": pal.accentMuted,
    "--bjork-accent-foreground": pal.accentFg,
    "--bjork-success": pal.success,
    "--bjork-warning": pal.warning,
    "--bjork-error": pal.error,
    "--bjork-ring-offset": pal.bg,
    colorScheme: tone,
  } as CSSProperties;
  return { tone, pal, style };
}

/** Classes for the shared keyboard focus ring. */
export const FOCUS_RING =
  "outline-none focus-visible:ring-2 focus-visible:ring-[color:var(--bjork-accent)] focus-visible:ring-offset-2 focus-visible:ring-offset-[color:var(--bjork-ring-offset)]";

/** Classes for the shared press feedback. */
export const PRESS = "transition-transform duration-150 ease-out active:scale-[0.97] motion-reduce:transition-none";

/**
 * Controlled-or-uncontrolled state. Pass `value` to control it; `onChange` fires for every change either way.
 */
export function useControllable<T>(
  value: T | undefined,
  defaultValue: T,
  onChange?: (next: T) => void,
): [T, (next: T) => void] {
  const controlled = value !== undefined;
  const [inner, setInner] = useState(defaultValue);
  const current = controlled ? value : inner;
  const onChangeRef = useRef(onChange);
  useLayoutEffect(() => {
    onChangeRef.current = onChange;
  });
  const set = useCallback(
    (next: T) => {
      if (!controlled) setInner(next);
      onChangeRef.current?.(next);
    },
    [controlled],
  );
  return [current, set];
}

/** 1234 -> "1,234", 18400 -> "18.4k", 1_200_000 -> "1.2M". */
export function formatTokens(n: number): string {
  if (n < 10_000) return Math.round(n).toLocaleString("en-US");
  if (n < 1_000_000) return `${(n / 1000).toFixed(n < 100_000 ? 1 : 0).replace(/\.0$/, "")}k`;
  return `${(n / 1_000_000).toFixed(n < 10_000_000 ? 2 : 1).replace(/\.?0+$/, "")}M`;
}

/** US dollars with sub-cent precision when it matters: 0.0042 -> "$0.0042", 12.5 -> "$12.50". */
export function formatCost(usd: number): string {
  if (usd === 0) return "$0.00";
  if (Math.abs(usd) < 0.01) return `$${usd.toFixed(4)}`;
  if (Math.abs(usd) < 1) return `$${usd.toFixed(3)}`;
  return `$${usd.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

/** 640 -> "640ms", 4200 -> "4.2s", 95000 -> "1m 35s". */
export function formatDuration(ms: number): string {
  if (ms < 1000) return `${Math.round(ms)}ms`;
  if (ms < 60_000) return `${(ms / 1000).toFixed(1)}s`;
  const m = Math.floor(ms / 60_000);
  const s = Math.round((ms % 60_000) / 1000);
  return `${m}m ${s}s`;
}

/** 2_400_000 bytes -> "2.4 MB". */
export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let v = bytes / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v.toFixed(v < 10 ? 1 : 0)} ${units[i]}`;
}

/** Shimmer keyframes for "working" text. Mount once with <style href=... precedence="default">. */
export const SHIMMER_TEXT_CSS =
  "@keyframes bjork-ai-shimmer{from{background-position:100% 0}to{background-position:0% 0}}" +
  ".bjork-ai-shimmer{background-image:linear-gradient(90deg,var(--bjork-text-muted) 0%,var(--bjork-text-muted) 40%,var(--bjork-text) 50%,var(--bjork-text-muted) 60%,var(--bjork-text-muted) 100%);background-size:300% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:bjork-ai-shimmer 1.8s linear infinite}" +
  "@media (prefers-reduced-motion: reduce){.bjork-ai-shimmer{animation:none;background:none;color:var(--bjork-text-muted)}}";

/** CANON §2. Panel = a component's own root surface; Card = a standalone card; Tile = a card inside a panel; Well = recessed code/field. */
export const AI_PANEL = "rounded-[20px] border border-[color:var(--bjork-border-muted)] bg-[color:var(--bjork-surface)] p-4 shadow-[var(--bjork-shadow-surface)]";
export const AI_CARD = "rounded-[18px] border border-[color:var(--bjork-border-muted)] bg-[color:var(--bjork-surface)] shadow-[var(--bjork-shadow-surface)]";
export const AI_TILE = "rounded-[12px] border border-[color:var(--bjork-border-muted)] bg-[color:var(--bjork-surface)] shadow-[var(--bjork-shadow-surface)]";
export const AI_WELL = "rounded-[8px] border border-[color:var(--bjork-border)] bg-[color:var(--bjork-field-inset)] shadow-[var(--bjork-shadow-inset)]";

export type BjorkTone = "dark" | "light";

// Canvas, WebGL and SVG attribute colours. DOM code uses the CSS tokens with these as fallbacks.
export const BJORK_PALETTE = {
  dark: {
    bg: "#050505", stage: "#111111", surface: "#121212", raised: "#161616", active: "#202020",
    border: "#232323", borderStrong: "#343434",
    text: "#ededed", textMedium: "rgba(237,237,237,0.72)", textMuted: "rgba(237,237,237,0.52)",
    textSoft: "rgba(237,237,237,0.36)", textFaint: "rgba(237,237,237,0.22)", hair: "rgba(237,237,237,0.12)",
    accent: "#ec5c13", accentInk: "#ec5c13", accentFill: "#b84a12", accentSoft: "rgba(236,92,19,0.12)", accentMuted: "rgba(236,92,19,0.24)",
    accentFg: "#fff2ea", success: "#4cc38a", warning: "#f2b544", error: "#ff5c4d",
  },
  light: {
    bg: "#f7f5ef", stage: "#f7f5ef", surface: "#fffcf6", raised: "#f5efe3", active: "#efe7d8",
    border: "#eee6db", borderStrong: "#e1d7c8",
    text: "#171717", textMedium: "rgba(23,23,23,0.72)", textMuted: "rgba(23,23,23,0.52)",
    textSoft: "rgba(23,23,23,0.36)", textFaint: "rgba(23,23,23,0.22)", hair: "rgba(23,23,23,0.10)",
    accent: "#ec7d43", accentInk: "#b4531f", accentFill: "#ec7d43", accentSoft: "rgba(236,125,67,0.10)", accentMuted: "rgba(236,125,67,0.20)",
    accentFg: "#3f2112", success: "#1f8a55", warning: "#a86b00", error: "#c8361f",
  },
} as const;

"use client";

import { useSyncExternalStore } from "react";
import { useTheme } from "next-themes";
import type { BjorkTone } from "./palette";

const subscribeNoop = () => () => {};
const getMounted = () => true;
const getServerMounted = () => false;

/**
 * Resolves the tone for a component. An explicit `tone` always wins.
 * Otherwise it follows next-themes' resolved theme, but only after mount,
 * so the server render and first client render agree on dark.
 */
export function useBjorkTone(tone?: BjorkTone): BjorkTone {
  const { resolvedTheme } = useTheme();
  const mounted = useSyncExternalStore(subscribeNoop, getMounted, getServerMounted);
  if (tone) return tone;
  if (!mounted) return "dark";
  return resolvedTheme === "light" ? "light" : "dark";
}

import type { CSSProperties } from "react";
import type { BjorkTone } from "./palette";

// The library surface (CANON.md §1). Values mirror app/globals.css :root and .dark. Change both together.
export const BJORK_SURFACE = {
  light: {
    surface: "#fffcf6", surfaceMuted: "rgba(250, 246, 237, 0.94)", surfaceHover: "#f5efe3", surfaceActive: "#efe7d8",
    panel: "#f8f2e7", menu: "rgba(255, 252, 246, 0.98)", field: "rgba(255, 252, 246, 0.96)",
